package com.hrm.gui;import com.hrm.service.ReportService;import javax.swing.*;import java.awt.*;import java.util.*;
public class ProjectPanel extends JPanel{JTable t=Ui.table(new String[]{"Dự án","Cần","Đã phân công","Còn thiếu"});JTextField q=new JTextField(18);public ProjectPanel(){setLayout(new BorderLayout(8,8));add(Ui.top("Nhu cầu nhân lực theo dự án"),BorderLayout.NORTH);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));b.add(new JLabel("Tìm dự án:"));b.add(q);JButton search=Ui.btn("Tìm kiếm"),members=Ui.btn("Xem nhân viên tham gia");b.add(search);b.add(members);add(b,BorderLayout.SOUTH);add(new JScrollPane(t),BorderLayout.CENTER);Runnable load=()->load();search.addActionListener(e->load.run());q.addActionListener(e->load.run());members.addActionListener(e->showMembers());load.run();}private void load(){try{var rows=new ArrayList<String[]>();String k=q.getText().trim().toLowerCase();for(String[] x:new ReportService().projects())if(k.isEmpty()||x[0].toLowerCase().contains(k))rows.add(x);Ui.fill(t,rows);}catch(Exception e){Ui.error(this,e);}}private void showMembers(){int r=t.getSelectedRow();if(r<0){JOptionPane.showMessageDialog(this,"Chọn dự án trước.");return;}String project=t.getValueAt(r,0).toString();try{JTable m=Ui.table(new String[]{"Mã NV","Họ tên","Vị trí","Phòng ban","Vai trò","Trạng thái"});Ui.fill(m,new ReportService().employeesByProject(project));JTextField s=new JTextField(15);JButton b=Ui.btn("Tìm");JPanel top=new JPanel();top.add(new JLabel("Tìm:"));top.add(s);top.add(b);JDialog d=new JDialog(SwingUtilities.getWindowAncestor(this),"Nhân viên tham gia - "+project,Dialog.ModalityType.APPLICATION_MODAL);d.setSize(900,500);d.setLocationRelativeTo(this);d.add(top,BorderLayout.NORTH);d.add(new JScrollPane(m),BorderLayout.CENTER);Runnable load=()->{try{Ui.fill(m,new ReportService().employeesByProject(project,s.getText().trim()));}catch(Exception e){Ui.error(d,e);}};b.addActionListener(e->load.run());d.setVisible(true);}catch(Exception e){Ui.error(this,e);}}}
